sys_variable_value.value:
(function execute(inputs, outputs) {

   var importer = new RBH_RiskAssessmentImport();
    var logs = importer.runImport(inputs.sysidattach); // 
    outputs.result = logs.join('\n');

    var hasError = logs.some(function(line) {
        return line.indexOf('❌') > -1;
    });
    outputs.haserror = hasError;

})(inputs, outputs);

